using System;using System.IO;using System.Reflection;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using Forms=System.Windows.Forms;
public static class DesignReview {
 public static int Demo(string folder){Directory.CreateDirectory(folder);var window=new MonitorWindow(true);try{var demo=Storage.DefaultServer();demo.Name="compute-node";demo.Host="10.0.0.8";window.CompactOptions.Servers.Clear();window.ChooseServer(demo);var sample=Program.Fixture("eight");foreach(var process in sample.Processes){process.Name="/workspace/train.py";process.User="researcher";}window.SetMetrics(sample,false);window.SwitchView("GPU");foreach(var theme in new[]{"graphite","forest"}){window.ApplyAppearance(theme);window.RenderImage(Path.Combine(folder,"demo-"+theme+".png"),1440,1000,144);}return 0;}finally{window.Exit();}}
 public static int Run(string folder){Directory.CreateDirectory(folder);var window=new MonitorWindow(true);try{window.SetMetrics(Program.Fixture("eight"),false);foreach(var page in new[]{"CPU","GPU","内存"}){window.SwitchView(page);window.RenderImage(Path.Combine(folder,page+".png"),1440,900,120);}var editor=new SettingsWindow(window.CompactOptions.Copy(),true);editor.RenderImage(Path.Combine(folder,"settings.png"),860,760,120);new AboutWindow(null,null).Render(Path.Combine(folder,"about.png"));
 var trayMethod=typeof(MonitorWindow).GetMethod("InitTray",BindingFlags.Instance|BindingFlags.NonPublic);trayMethod.Invoke(window,null);var tray=(Forms.NotifyIcon)typeof(MonitorWindow).GetField("tray",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(window);var menu=tray.ContextMenuStrip;if(menu!=null){menu.PerformLayout();using(var bmp=new System.Drawing.Bitmap(menu.Width,menu.Height)){menu.DrawToBitmap(bmp,new System.Drawing.Rectangle(System.Drawing.Point.Empty,menu.Size));bmp.Save(Path.Combine(folder,"tray-before.png"),System.Drawing.Imaging.ImageFormat.Png);}}
 new TrayFlyout("aq-server",()=>{},()=>{},()=>{},()=>{},()=>{},()=>true,value=>{}).Render(Path.Combine(folder,"tray-after.png"));return 0;}finally{window.Exit();}}
}
